package io.github.shiokunn.trpg.core.domain

import kotlinx.serialization.Serializable

/**
 * A free-form skill. Names are generated by the AI or entered by the player,
 * so they are never restricted to a fixed enum.
 */
@Serializable
data class Skill(
    val id: String,
    val name: String,
    val level: Int = 0,
    val description: String = "",
) {
    fun clamped(): Skill = copy(level = level.coerceIn(MIN_LEVEL, MAX_LEVEL))

    companion object {
        const val MIN_LEVEL = 0
        const val MAX_LEVEL = 3
        const val MAX_CREATION_LEVEL = 2
    }
}

@Serializable
data class Item(
    val id: String,
    val name: String,
    val description: String = "",
    val quantity: Int = 1,
    val type: String = "misc",
    val equipped: Boolean = false,
    /** Abstract offensive power used by the combat formula. */
    val power: Int = 0,
    /** Abstract defense value used by the combat formula. */
    val defense: Int = 0,
    val tags: List<String> = emptyList(),
) {
    fun normalized(): Item = copy(quantity = quantity.coerceIn(0, MAX_QUANTITY))

    companion object {
        const val MAX_QUANTITY = 99
    }
}
